pub fn setup_runtime(vm: &mut Vm, argv: Vec<String>) {
    vm.host.argv = argv.clone();
    vm.host.exec_path = argv.first().cloned().unwrap_or_default();
    console::setup(vm);
    timers::setup(vm);
    process::setup(vm);
