}

fn print_fn(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let parts: Vec<String> = a.args.iter().map(|v| display_value(vm, v)).collect();
    write_stdout(vm, &format!("{}\n", parts.join(" ")));
    Ok(Value::Undefined)
}

