    Value::Obj(o)
}

fn meminfo(key: &str) -> f64 {
    if let Ok(s) = std::fs::read_to_string("/proc/meminfo") {
        for line in s.lines() {
            if let Some(rest) = line.strip_prefix(&format!("{}:", key)) {
                let kb: f64 = rest.trim().trim_end_matches("kB").trim().parse().unwrap_or(0.0);
                return kb * 1024.0;
            }
        }
    }
    0.0
}

