    let mut guard = match POOL.lock() {
        Ok(g) => g,
        Err(p) => p.into_inner(),
    };
    let pool = guard.get_or_insert_with(|| Pool { file: None, buf: Box::new([0u8; POOL_SIZE]), pos: POOL_SIZE });
    if buf.len() > POOL_SIZE / 2 {
        read_os(&mut pool.file, buf);
        return;
