pub fn throw_dt_error<T>(vm: &mut Vm, e: dt::DateTimeError) -> JsResult<T> {
    match e.kind {
        dt::ErrorKind::Range => vm.throw_range(e.message),
        dt::ErrorKind::Type => vm.throw_type(e.message),
    }
}

